export const LOGO_DATA_URI = `data:image/svg+xml;base64,${Buffer.from(AUTOSCHOLAR_LOGO_SVG).toString('base64')}`;

export interface MarkdownPDFOptions {
  question: string;
  answer: string;
}

function convertImagesToBase64(markdown: string): string {
  const imageRegex = /!\[([^\]]*)\]\(\/figures\/([^)]+)\)/g;

  let result = markdown;
  let match;

  while ((match = imageRegex.exec(markdown)) !== null) {
    const altText = match[1];
    const filename = match[2];
    const fullMatch = match[0];

    const imagePath = path.join(process.cwd(), 'dist', 'public', 'figures', filename);

    try {
      if (fs.existsSync(imagePath)) {
        const imageBuffer = fs.readFileSync(imagePath);
        const base64Image = imageBuffer.toString('base64');
        const mimeType = 'image/png';

        const dataUrl = `data:${mimeType};base64,${base64Image}`;
        const replacement = `![${altText}](${dataUrl})`;

        result = result.replace(fullMatch, replacement);
        console.log(`✓ Converted image to base64: ${filename}`);
      } else {
        console.warn(`⚠ Image not found: ${imagePath}`);
      }
    } catch (error) {
      console.error(`✗ Error reading image ${filename}:`, (error as Error).message);
    }
  }

  return result;
}

export function markdownToHTML(markdown: string, title: string): string {
  const markdownWithBase64Images = convertImagesToBase64(markdown);

  let protected_ = markdownWithBase64Images;
  const mathBlocks: string[] = [];

  const currencyPlaceholders: string[] = [];
  protected_ = protected_.replace(/\$(\d[\d,]*\.?\d*)/g, (_match, amount) => {
    const idx = currencyPlaceholders.length;
    currencyPlaceholders.push(amount);
    return `%%CURRENCY${idx}%%`;
  });

  protected_ = protected_.replace(/\$\$([\s\S]+?)\$\$/g, (_match, expr) => {
    const idx = mathBlocks.length;
    mathBlocks.push(expr);
    return `%%DISPLAYMATH${idx}%%`;
  });

  protected_ = protected_.replace(/\$([^\$\n*_]+?)\$/g, (_match, expr) => {
    if (/^\s*[\d.,]+\s*$/.test(expr)) return _match;
    const idx = mathBlocks.length;
    mathBlocks.push(expr);
    return `%%INLINEMATH${idx}%%`;
  });

  protected_ = protected_.replace(/%%CURRENCY(\d+)%%/g, (_m, idx) => {
    return `$${currencyPlaceholders[parseInt(idx)]}`;
  });

  let htmlBody = marked.parse(protected_) as string;

  htmlBody = htmlBody.replace(/%%DISPLAYMATH(\d+)%%/g, (_m, idx) => {
    return `<span class="math-display">\\[${mathBlocks[parseInt(idx)]}\\]</span>`;
  });
  htmlBody = htmlBody.replace(/%%INLINEMATH(\d+)%%/g, (_m, idx) => {
    return `<span class="math-inline">\\(${mathBlocks[parseInt(idx)]}\\)</span>`;
  });

  htmlBody = htmlBody.replace(/<table>/g, '<div class="table-wrapper"><table>');
  htmlBody = htmlBody.replace(/<\/table>/g, '</table></div>');

  return `
<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>${title}</title>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.css">
  <script defer src="https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.js"></script>
  <script defer src="https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/contrib/auto-render.min.js"
    onload="renderMathInElement(document.body, {delimiters:[{left:'\\\\[',right:'\\\\]',display:true},{left:'\\\\(',right:'\\\\)',display:false}],throwOnError:false});"></script>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      line-height: 1.6;
      color: #1f2937;
      padding: 40px;
      max-width: 800px;
      margin: 0 auto;
    }

    h1, h2, h3, h4, h5, h6 {
      color: #111827;
      margin-top: 1.5em;
      margin-bottom: 0.5em;
      font-weight: 600;
    }

    h1 {
      font-size: 2em;
      color: #6366f1;
      border-bottom: 3px solid #6366f1;
      padding-bottom: 0.3em;
    }

    h2 {
      font-size: 1.5em;
      color: #4f46e5;
    }

    h3 {
      font-size: 1.25em;
    }

    p {
      margin-bottom: 1em;
    }

    ul, ol {
      margin-left: 2em;
      margin-bottom: 1em;
    }

    code {
      background: #f3f4f6;
      padding: 0.2em 0.4em;
      border-radius: 3px;
      font-family: 'Monaco', 'Courier New', monospace;
      font-size: 0.9em;
    }

    pre {
      background: #1f2937;
      color: #f9fafb;
      padding: 1em;
      border-radius: 6px;
      overflow-x: auto;
      margin-bottom: 1em;
    }

    pre code {
      background: none;
      color: #f9fafb;
      padding: 0;
    }

    /* --- Table wrapper for overflow on wide tables --- */
    .table-wrapper {
      width: 100%;
      overflow-x: auto;
      margin-bottom: 1.5em;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 1.5em;
      font-size: 0.85em;
      page-break-inside: auto;
      border: 1px solid #d1d5db;
      border-radius: 6px;
      overflow: hidden;
    }

    thead {
      display: table-header-group;
    }

    tr {
      page-break-inside: avoid;
      page-break-after: auto;
    }

    th, td {
      border: 1px solid #e5e7eb;
      padding: 0.5em 0.65em;
      text-align: left;
      word-wrap: break-word;
      overflow-wrap: break-word;
      max-width: 220px;
    }

    th {
      background: linear-gradient(180deg, #f8f9fb 0%, #eef0f4 100%);
      font-weight: 600;
      color: #374151;
      white-space: nowrap;
      font-size: 0.92em;
      border-bottom: 2px solid #d1d5db;
    }

    tbody tr:nth-child(even) {
      background-color: #f9fafb;
    }

    tbody tr:hover {
      background-color: #f3f4f6;
    }

    td {
      color: #4b5563;
    }

    /* Numeric cells: right-align columns that look numeric */
    td:not(:first-child) {
      font-variant-numeric: tabular-nums;
    }

    img {
      max-width: 100%;
      height: auto;
      display: block;
      margin: 1em 0;
    }

    blockquote {
      border-left: 4px solid #6366f1;
      padding-left: 1em;
      margin-left: 0;
      color: #6b7280;
      font-style: italic;
    }

    strong {
      font-weight: 600;
      color: #111827;
    }

    em {
      font-style: italic;
      color: #4b5563;
    }

    .cover-page {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 70vh;
      text-align: center;
      page-break-after: always;
    }

    .cover-logo {
      width: 180px;
      height: 180px;
      margin-bottom: 2em;
    }

    .cover-title {
      font-size: 2.5em;
      font-weight: 700;
      background: linear-gradient(135deg, #119993, #2072B2, #652E89);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin-bottom: 0.3em;
    }

    .cover-subtitle {
      font-size: 1.1em;
      color: #6b7280;
      margin-bottom: 2em;
    }

    .cover-date {
      font-size: 0.9em;
      color: #9ca3af;
    }

    .cover-divider {
      width: 120px;
      height: 3px;
      background: linear-gradient(90deg, #119993, #2072B2, #652E89);
      border: none;
      margin: 1.5em auto;
      border-radius: 2px;
    }
  </style>
</head>
<body>
  <div class="cover-page">
    <img src="${LOGO_DATA_URI}" class="cover-logo" alt="AutoScholar" />
    <div class="cover-title">AutoScholar</div>
    <div class="cover-subtitle">Financial Intelligence Platform</div>
    <hr class="cover-divider" />
    <div class="cover-date">${new Date().toLocaleDateString('fr-FR', { year: 'numeric', month: 'long', day: 'numeric' })}</div>
  </div>
  <div class="content">
    ${htmlBody}
  </div>
  <script>
    // Auto-shrink tables that overflow page width
    document.querySelectorAll('table').forEach(function(table) {
      var wrapper = table.parentElement;
      if (!wrapper) return;
      var containerWidth = wrapper.parentElement ? wrapper.parentElement.clientWidth : document.body.clientWidth;
      var tableWidth = table.scrollWidth;
      if (tableWidth > containerWidth) {
        var scale = Math.max(0.55, containerWidth / tableWidth);
        table.style.fontSize = (scale * 100) + '%';
      }
      // If table has many columns (>6), reduce padding
      var cols = table.querySelectorAll('thead th, thead td');
      if (cols.length > 6) {
        table.style.fontSize = '0.75em';
        table.querySelectorAll('th, td').forEach(function(cell) {
          cell.style.padding = '0.3em 0.4em';
        });
      }
    });
  </script>
</body>
</html>`;
}
